// Kopya Chrome profiline CDP uzerinden baglanan kucuk surucu.
// Kullanim: node tarayici.mjs <komut> [arg...]
//   goto <url>            sayfaya git, url+baslik yaz
//   shot <dosya>          ekran goruntusu (tam sayfa degil, gorunur alan)
//   text                  sayfanin gorunur metni (ilk 6000 karakter)
//   click <css>           secicideki ogeye tikla
//   clicktext <metin>     metni iceren ilk tiklanabilir ogeye tikla
//   type <css> <metin>    alana yaz (once temizler)
//   press <tus>           klavye tusu (Enter, Tab...)
//   eval <js>             sayfada js calistir, sonucu yaz
//   url                   mevcut url
//   wait <ms>             bekle
import puppeteer from 'C:/Users/orcns/projects/cloud/mobil/node_modules/puppeteer-core/lib/esm/puppeteer/puppeteer-core.js';
import fs from 'node:fs';

const PORT = 9333;
const [komut, ...args] = process.argv.slice(2);

const browser = await puppeteer.connect({ browserURL: `http://127.0.0.1:${PORT}`, defaultViewport: null });
const pages = await browser.pages();
let page = pages.find(p => !p.url().startsWith('devtools')) ?? (await browser.newPage());
// En son acilan sekmeyi tercih et (popup vb.)
page = pages.length ? pages[pages.length - 1] : page;
page.setDefaultTimeout(20000);

const bekle = (ms) => new Promise(r => setTimeout(r, ms));
const durum = async () => `${page.url()}\n[${await page.title()}]`;

try {
  switch (komut) {
    case 'goto':
      await page.goto(args[0], { waitUntil: 'domcontentloaded', timeout: 45000 });
      await bekle(2500);
      console.log(await durum());
      break;
    case 'shot':
      await page.screenshot({ path: args[0] });
      console.log('yazildi', args[0]);
      break;
    case 'text': {
      const t = await page.evaluate(() => document.body.innerText);
      console.log(t.slice(0, Number(args[0] ?? 6000)));
      break;
    }
    case 'click':
      await page.click(args[0]);
      await bekle(1500);
      console.log(await durum());
      break;
    case 'clicktext': {
      const ok = await page.evaluate((m) => {
        const adaylar = [...document.querySelectorAll('button, a, [role=button], [role=menuitem], [role=option], [role=tab], li, span, div')];
        const el = adaylar.find(e => e.innerText && e.innerText.trim() === m && e.offsetParent !== null)
          ?? adaylar.find(e => e.innerText && e.innerText.trim().includes(m) && e.offsetParent !== null);
        if (!el) return false;
        el.scrollIntoView({ block: 'center' });
        el.click();
        return true;
      }, args[0]);
      await bekle(1500);
      console.log(ok ? 'tiklandi' : 'BULUNAMADI', '\n' + await durum());
      break;
    }
    case 'type':
      await page.click(args[0], { clickCount: 3 });
      await page.keyboard.press('Backspace');
      await page.type(args[0], args.slice(1).join(' '), { delay: 20 });
      console.log('yazildi');
      break;
    case 'press':
      await page.keyboard.press(args[0]);
      await bekle(1500);
      console.log(await durum());
      break;
    case 'eval': {
      const r = await page.evaluate(args.join(' '));
      console.log(typeof r === 'string' ? r : JSON.stringify(r, null, 1));
      break;
    }
    case 'url':
      console.log(await durum());
      break;
    case 'wait':
      await bekle(Number(args[0]));
      console.log(await durum());
      break;
    default:
      console.log('bilinmeyen komut');
  }
} finally {
  browser.disconnect();
}

